(7466583, 1185092, 113411, '<td valign="top">too fabulous!!!!</td>', 'too fabulous!!!!', '2016-08-01 01:33:42.000000', NULL, 1),
(7466585, 1185060, 182284, '<td valign="top">Precious photo. I love baby pigs, they are nice and sharp in your photo.</td>', 'Precious photo. I love baby pigs, they are nice and sharp in your photo.', '2016-08-01 01:51:04.000000', NULL, 1),
(7466605, 1185220, 156466, '<td valign="top">Part of me longs to see this connect with land somehow.  It''s lovely but a but disconnected.</td>', 'Part of me longs to see this connect with land somehow.  It''s lovely but a but disconnected.', '2016-08-01 11:13:21.000000', NULL, 1),
(7466606, 1184681, 156466, '<td valign="top">Well seen but just too much foreground in my opinion. Maybe a square crop so you get a little closer to the girl, who is easy to miss here.</td>', 'Well seen but just too much foreground in my opinion. Maybe a square crop so you get a little closer to the girl, who is easy to miss here.', '2016-08-01 11:15:06.000000', NULL, 1),
(7466607, 1184933, 156466, '<td valign="top">I''m sure this will do well, but the processing is just a little too heavy handed for me.  Halos ad lots of cloud structure pull me from the wonderful beams of light you have here.</td>', 'I''m sure this will do well, but the processing is just a little too heavy handed for me.  Halos ad lots of cloud structure pull me from the wonderful beams of light you have here.', '2016-08-01 11:18:04.000000', NULL, 1),
(7466608, 1185090, 156466, '<td valign="top">Great perspective, but as great as the view is the OOF foreground kills it. That spiral and the rock dead center need to be in focus too. It''s just fuzzy enough to make me have to blink over and over and over thinking it''s me.</td>', 'Great perspective, but as great as the view is the OOF foreground kills it. That spiral and the rock dead center need to be in focus too. It''s just fuzzy enough to make me have to blink over and over and over thinking it''s me.', '2016-08-01 11:20:09.000000', NULL, 1),
(7466609, 1185077, 156466, '<td valign="top">Two great photos here, with each one getting lost in the other. If I scroll so the white flowers are out of the shot I love it.  As is, I lose the pelican and would almost rather have had you lose the reflection to give me more up top. There''s so much nice here but it''s not coming together nicely for me.</td>', 'Two great photos here, with each one getting lost in the other. If I scroll so the white flowers are out of the shot I love it.  As is, I lose the pelican and would almost rather have had you lose the reflection to give me more up top. There''s so much nice here but it''s not coming together nicely for me.', '2016-08-01 11:23:40.000000', NULL, 1),
(7466611, 1184415, 156466, '<td valign="top">Gotta love when you''re facing the right direction at the right time.  Wonderful capture.</td>', 'Gotta love when you''re facing the right direction at the right time.  Wonderful capture.', '2016-08-01 11:24:12.000000', NULL, 1),
(7466612, 1184729, 156466, '<td valign="top">Yep. That''ll work. Nice painterly look without painterly effects.</td>', 'Yep. That''ll work. Nice painterly look without painterly effects.', '2016-08-01 11:25:31.000000', NULL, 1),
(7466613, 1185152, 156466, '<td valign="top">Really spectacular grab that feels just a little flat in the processing. I admire the restraint but wish you''d done just a bit more with the shadowed areas.</td>', 'Really spectacular grab that feels just a little flat in the processing. I admire the restraint but wish you''d done just a bit more with the shadowed areas.', '2016-08-01 11:31:21.000000', NULL, 1),
